                                                           " is outside of the image area (Ysiz=%u).",
                                                           start_y, image->y1);
                 return false;
          }
          else
          {
                 tilesToDecompress.y0 = uint16_t((start_y - cp_.ty0) / cp_.t_height);
                 compositeImage->y0 = start_y;
          }

          /* Right */
          assert(end_x > 0);
          assert(end_y > 0);
